import { TransformNode, SceneLoader, Vector3 } from '@babylonjs/core';
import { applyModelPaint } from '../../../utils/modelPaint.js';

// Light turret — M24 Chaffee-inspired, generated by scripts/modelgen/light_turret_enclosed.py.
// ringDiameter mirrors ringD in params/light_tank.json.

const PAINT = { paintColor: [0.78, 0.12, 0.08] };

export default {
  id: 'light-turret-enclosed',
  name: 'Light Turret (Enclosed)',
  category: 'turret',
  stats: { traverseSpeed: 88 },
  mountEmpty: 'mount',
  defaultCannon: 'light-gun-75mm',
  ringDiameter: 1.6,   // mirrors ringD in scripts/modelgen/params/
  paintColor: PAINT.paintColor,

  async build(scene, paintOverride = null) {
    const result = await SceneLoader.ImportMeshAsync('', '/assets/models/tanks/parts/', 'light_turret_enclosed.glb', scene);
    const mountNode = result.transformNodes.find(n => n.name === this.mountEmpty);
    const mount = mountNode ? mountNode.getAbsolutePosition().clone() : new Vector3(0, 0.30, 0.80);

    const root = new TransformNode('turret_light_enclosed_root', scene);
    const meshes = result.meshes.filter(m => m.name !== '__root__');
    for (const m of meshes) m.setParent(root);
    for (const m of meshes) m.computeWorldMatrix(true);

    applyModelPaint(meshes, PAINT, scene, paintOverride);
    return { root, meshes, mount };
  },
};
